def read_system_nameservers() -> list[str]:
    try:
        with open("/etc/resolv.conf", "r", encoding="utf-8") as handle:
            nameservers = []
            for line in handle:
                stripped = line.strip()
                if not stripped or stripped.startswith("#") or stripped.startswith(";"):
                    continue
                fields = stripped.split()
                if len(fields) >= 2 and fields[0] == "nameserver":
                    nameservers.append(fields[1])
            if nameservers:
                return nameservers
    except OSError as exc:
        raise SystemNameserverError(str(exc)) from exc
    raise SystemNameserverError("failed to read system nameserver information")


def encode_name(name: str) -> bytes:
    normalized = name.rstrip(".")
    if not normalized:
        return b"\x00"
    labels = normalized.split(".")
    out = bytearray()
    for label in labels:
        encoded = label.encode("idna")
        if len(encoded) > 63:
            raise InvalidOptions(f'Invalid query name "{name}"')
        out.append(len(encoded))
        out.extend(encoded)
    out.append(0)
    return bytes(out)


def build_query(domain: str, qtype: int, qclass: int, txid: int, options: Options) -> bytes:
    flags = 0x0100
    if options.tweaks.authoritative:
        flags |= 0x0400
    if options.tweaks.authentic_data:
        flags |= 0x0020
    if options.tweaks.checking_disabled:
        flags |= 0x0010

    question = encode_name(domain) + qtype.to_bytes(2, "big") + qclass.to_bytes(2, "big")
    additionals = b""
    arcount = 0
    if options.edns != "disable":
        payload_size = options.tweaks.udp_payload_size or 512
        additionals = b"\x00" + (41).to_bytes(2, "big") + payload_size.to_bytes(2, "big") + (0).to_bytes(4, "big") + (0).to_bytes(2, "big")
        arcount = 1

    header = (
        txid.to_bytes(2, "big")
        + flags.to_bytes(2, "big")
        + (1).to_bytes(2, "big")
        + (0).to_bytes(2, "big")
        + (0).to_bytes(2, "big")
        + arcount.to_bytes(2, "big")
    )
    return header + question + additionals


def decode_name(packet: bytes, offset: int, depth: int = 0) -> tuple[str, int]:
    if depth > 20:
        raise ProtocolError("Malformed packet: too many compressed labels")

    labels: list[str] = []
    cursor = offset
    end_offset: int | None = None

    while True:
        if cursor >= len(packet):
            raise ProtocolError("Malformed packet: insufficient data")
        length = packet[cursor]
        if length & 0xC0 == 0xC0:
            if cursor + 1 >= len(packet):
                raise ProtocolError("Malformed packet: insufficient data")
            pointer = ((length & 0x3F) << 8) | packet[cursor + 1]
            if end_offset is None:
                end_offset = cursor + 2
            cursor = pointer
            depth += 1
            if depth > 20:
                raise ProtocolError("Malformed packet: too many compressed labels")
            continue
        if length & 0xC0:
            raise ProtocolError("Malformed packet: invalid label")
        cursor += 1
        if length == 0:
            break
        if cursor + length > len(packet):
            raise ProtocolError("Malformed packet: insufficient data")
        label = packet[cursor : cursor + length].decode("ascii", "replace")
        labels.append(label)
        cursor += length

    name = "." if not labels else ".".join(labels) + "."
    return name, end_offset if end_offset is not None else cursor


def parse_question(packet: bytes, offset: int) -> tuple[Question, int]:
    name, offset = decode_name(packet, offset)
    if offset + 4 > len(packet):
        raise ProtocolError("Malformed packet: insufficient data")
    qtype = int.from_bytes(packet[offset : offset + 2], "big")
    qclass = int.from_bytes(packet[offset + 2 : offset + 4], "big")
    return Question(name=name, qtype=qtype, qclass=qclass), offset + 4


def parse_record(packet: bytes, offset: int) -> tuple[Record, int]:
    name, offset = decode_name(packet, offset)
    if offset + 10 > len(packet):
        raise ProtocolError("Malformed packet: insufficient data")
    type_code = int.from_bytes(packet[offset : offset + 2], "big")
    class_code = int.from_bytes(packet[offset + 2 : offset + 4], "big")
    ttl = int.from_bytes(packet[offset + 4 : offset + 8], "big")
    rdlength = int.from_bytes(packet[offset + 8 : offset + 10], "big")
    offset += 10
    if offset + rdlength > len(packet):
        raise ProtocolError("Malformed packet: insufficient data")
    rdata = packet[offset : offset + rdlength]
    offset += rdlength

    if type_code == TYPE_NAME_TO_CODE["OPT"]:
        return (
            Record(
                name="",
                type_code=type_code,
                class_code=class_code,
                ttl=0,
                rdata=rdata,
                udp_payload_size=class_code,
                ext_rcode=(ttl >> 24) & 0xFF,
                version=(ttl >> 16) & 0xFF,
                flags=ttl & 0xFFFF,
            ),
            offset,
        )

    return Record(name=name, type_code=type_code, class_code=class_code, ttl=ttl, rdata=rdata), offset


def parse_response(packet: bytes) -> Response:
    if len(packet) < 12:
        raise ProtocolError("Malformed packet: insufficient data")
    txid = int.from_bytes(packet[0:2], "big")
    flags = int.from_bytes(packet[2:4], "big")
    qdcount = int.from_bytes(packet[4:6], "big")
    ancount = int.from_bytes(packet[6:8], "big")
    nscount = int.from_bytes(packet[8:10], "big")
    arcount = int.from_bytes(packet[10:12], "big")

    offset = 12
    queries: list[Question] = []
    answers: list[Record] = []
    authorities: list[Record] = []
    additionals: list[Record] = []

    for _ in range(qdcount):
        question, offset = parse_question(packet, offset)
        queries.append(question)
    for _ in range(ancount):
        record, offset = parse_record(packet, offset)
        answers.append(record)
    for _ in range(nscount):
        record, offset = parse_record(packet, offset)
        authorities.append(record)
    for _ in range(arcount):
        record, offset = parse_record(packet, offset)
        additionals.append(record)

    return Response(
        txid=txid,
        flags=flags,
        rcode=flags & 0x000F,
        truncated=bool(flags & 0x0200),
        queries=queries,
        answers=answers,
        authorities=authorities,
        additionals=additionals,
    )


def split_host_port(value: str, default_port: int) -> tuple[str, int]:
    if value.startswith("["):
        end = value.find("]")
        if end == -1:
            return value, default_port
        host = value[1:end]
        rest = value[end + 1 :]
        if rest.startswith(":") and rest[1:].isdigit():
            return host, int(rest[1:], 10)
        return host, default_port
    if value.count(":") == 1 and value.rsplit(":", 1)[1].isdigit():
        host, port = value.rsplit(":", 1)
        return host, int(port, 10)
    return value, default_port


def format_network_error(exc: BaseException) -> str:
    if isinstance(exc, socket.gaierror):
        detail = exc.strerror or (exc.args[1] if len(exc.args) > 1 else str(exc))
        return f"failed to lookup address information: {detail}"
    if isinstance(exc, OSError) and getattr(exc, "errno", None) is not None:
        detail = exc.strerror or str(exc)
        return f"{detail} (os error {exc.errno})"
    return str(exc)


def format_tls_error(exc: BaseException) -> str:
    if isinstance(exc, ssl.SSLCertVerificationError):
        reason = getattr(exc, "verify_message", None) or str(exc)
        return (
            "error:1416F086:SSL routines:tls_process_server_certificate:"
            f"certificate verify failed:ssl/statem/statem_clnt.c:1913: ({reason})"
        )
    return str(exc)


def first_addrinfo(host: str, port: int, socktype: int) -> tuple[int, int, int, str, tuple[Any, ...]]:
    infos = socket.getaddrinfo(host, port, 0, socktype)
    if not infos:
        raise OSError("failed to resolve nameserver")
    return infos[0]


def transport_udp(host: str, port: int, payload: bytes) -> bytes:
    family, socktype, proto, _, sockaddr = first_addrinfo(host, port, socket.SOCK_DGRAM)
    with socket.socket(family, socktype, proto) as sock:
        sock.settimeout(5.0)
        sock.connect(sockaddr)
        sock.send(payload)
        return sock.recv(4096)


def recv_exact(sock: socket.socket, size: int) -> bytes:
    chunks = bytearray()
    while len(chunks) < size:
        chunk = sock.recv(size - len(chunks))
        if not chunk:
            raise ProtocolError("Malformed packet: insufficient data")
        chunks.extend(chunk)
    return bytes(chunks)


def transport_tcp(host: str, port: int, payload: bytes) -> bytes:
    with socket.create_connection((host, port), timeout=5.0) as sock:
        sock.sendall(len(payload).to_bytes(2, "big") + payload)
        length = int.from_bytes(recv_exact(sock, 2), "big")
        return recv_exact(sock, length)


def transport_tls(host: str, port: int, payload: bytes) -> bytes:
    context = ssl.create_default_context()
    with socket.create_connection((host, port), timeout=5.0) as raw:
        with context.wrap_socket(raw, server_hostname=host) as sock:
            sock.sendall(len(payload).to_bytes(2, "big") + payload)
            length = int.from_bytes(recv_exact(sock, 2), "big")
            return recv_exact(sock, length)


def read_http_response(sock: socket.socket) -> tuple[int, dict[str, str], bytes]:
    data = bytearray()
    while b"\r\n\r\n" not in data:
        chunk = sock.recv(4096)
        if not chunk:
            raise ProtocolError("Malformed packet: insufficient data")
        data.extend(chunk)
    head, body = bytes(data).split(b"\r\n\r\n", 1)
    lines = head.decode("iso-8859-1").split("\r\n")
    status_line = lines[0]
    parts = status_line.split(" ", 2)
    if len(parts) < 2 or not parts[1].isdigit():
        raise ProtocolError("Malformed packet: invalid HTTP response")
    status = int(parts[1], 10)
    headers: dict[str, str] = {}
    for line in lines[1:]:
        if ":" in line:
            key, value = line.split(":", 1)
            headers[key.strip().lower()] = value.strip()

    if "content-length" in headers:
        expected = int(headers["content-length"], 10)
        while len(body) < expected:
            chunk = sock.recv(4096)
            if not chunk:
                break
            body += chunk
        body = body[:expected]
    else:
        while True:
            chunk = sock.recv(4096)
            if not chunk:
                break
            body += chunk
    return status, headers, body


def transport_https(url: str, payload: bytes) -> bytes:
    parsed = urllib.parse.urlparse(url)
    if parsed.scheme != "https" or not parsed.netloc:
        raise PanicError("Invalid HTTPS nameserver")

    connect_host = parsed.netloc
    request_path = parsed.path or "/"
    if parsed.query:
        request_path += "?" + parsed.query

    context = ssl.create_default_context()
    with socket.create_connection((connect_host, 443), timeout=5.0) as raw:
        with context.wrap_socket(raw, server_hostname=connect_host) as sock:
            request = (
                f"POST {request_path} HTTP/1.1\r\n"
                f"Host: {connect_host}\r\n"
                "Content-Type: application/dns-message\r\n"
                "Accept: application/dns-message\r\n"
                "User-Agent: dog/0.2.0-pre\r\n"
                f"Content-Length: {len(payload)}\r\n"
                "Connection: close\r\n"
                "\r\n"
            ).encode("ascii") + payload
            sock.sendall(request)
            status, _, body = read_http_response(sock)
            if status != 200:
                raise ProtocolError(f"Malformed packet: HTTP status {status}")
            return body


def rr_domain(packet: bytes, rr: Record) -> str:
    if not rr.rdata:
        raise ProtocolError("Malformed packet: insufficient data")
    value, _ = decode_name(packet, rr._rdata_offset)  # type: ignore[attr-defined]
    return value


def record_with_packet(packet: bytes, rr: Record, rdata_offset: int) -> Record:
    setattr(rr, "_packet", packet)
    setattr(rr, "_rdata_offset", rdata_offset)
    return rr


def parse_record(packet: bytes, offset: int) -> tuple[Record, int]:
    name, offset = decode_name(packet, offset)
    if offset + 10 > len(packet):
        raise ProtocolError("Malformed packet: insufficient data")
    type_code = int.from_bytes(packet[offset : offset + 2], "big")
    class_code = int.from_bytes(packet[offset + 2 : offset + 4], "big")
    ttl = int.from_bytes(packet[offset + 4 : offset + 8], "big")
    rdlength = int.from_bytes(packet[offset + 8 : offset + 10], "big")
    offset += 10
    rdata_offset = offset
    if offset + rdlength > len(packet):
        raise ProtocolError("Malformed packet: insufficient data")
    rdata = packet[offset : offset + rdlength]
    offset += rdlength

    if type_code == TYPE_NAME_TO_CODE["OPT"]:
        rr = Record(
            name="",
            type_code=type_code,
            class_code=class_code,
            ttl=0,
            rdata=rdata,
            udp_payload_size=class_code,
            ext_rcode=(ttl >> 24) & 0xFF,
            version=(ttl >> 16) & 0xFF,
            flags=ttl & 0xFFFF,
        )
        return rr, offset

    rr = Record(name=name, type_code=type_code, class_code=class_code, ttl=ttl, rdata=rdata)
    return record_with_packet(packet, rr, rdata_offset), offset


def decode_character_string(blob: bytes, offset: int) -> tuple[str, int]:
    if offset >= len(blob):
        raise ProtocolError("Malformed packet: insufficient data")
    length = blob[offset]
    offset += 1
    if offset + length > len(blob):
        raise ProtocolError("Malformed packet: insufficient data")
    value = blob[offset : offset + length].decode("utf-8", "replace")
    return value, offset + length
